+
+func TestHydratePointerCommands(t *testing.T) {
+	type cmd struct {
+		Flag bool
+	}
+
+	var cli struct {
+		Cmd *cmd `cmd:""`
+	}
+
+	k := mustNew(t, &cli)
+	_, err := k.Parse([]string{"cmd", "--flag"})
+	require.NoError(t, err)
+	require.Equal(t, &cmd{Flag: true}, cli.Cmd)
+}
